def get_exotic_integers(limit):
    """Generates all prime powers up to a given limit."""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    primes = []
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    exotic_numbers = set()

    # Generate powers p^k for every prime p
    for p in primes:
        power = p
        while power <= limit:
            exotic_numbers.add(power)
            # Check for overflow potential before multiplying, although for small limit this is fine
            if power > limit // p:
                break
            power *= p

    return sorted(list(exotic_numbers))

# Estimate needed limit. The 132nd prime itself is 751. Prime powers grow slower than primes.
# Let's start with a generous limit, say 1000, to ensure we capture the 132nd element.
limit = 1000
exotic_list = get_exotic_integers(limit)

# Check the count and find the 132nd element
if len(exotic_list) >= 132:
    print(f"The 132nd exotic integer is: {exotic_list[131]}")
else:
    print(f"Limit {limit} was too small. Found only {len(exotic_list)} elements.")
